#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    std::vector<int> kWeakestRows(std::vector<std::vector<int>>& mat, int k) {
        std::vector<std::pair<int, int>> pairs;
        for (int i = 0; i < (int)mat.size(); ++i) {
            int count = std::accumulate(mat[i].begin(), mat[i].end(), 0);
            pairs.push_back({count, i});
        }
        std::sort(pairs.begin(), pairs.end());
        std::vector<int> res;
        for (int i = 0; i < k; ++i) res.push_back(pairs[i].second);
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] kWeakestRows(int[][] mat, int k) {
        int m = mat.length;
        int[][] pairs = new int[m][2];
        for (int i = 0; i < m; i++) {
            int count = 0;
            for (int x : mat[i]) count += x;
            pairs[i][0] = count;
            pairs[i][1] = i;
        }
        Arrays.sort(pairs, (a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });
        int[] res = new int[k];
        for (int i = 0; i < k; i++) res[i] = pairs[i][1];
        return res;
    }
}

var kWeakestRows = function(mat, k) {
    const pairs = mat.map((row, i) => [row.reduce((acc, v) => acc + v, 0), i]);
    pairs.sort((a, b) => {
        if (a[0] !== b[0]) return a[0] - b[0];
        return a[1] - b[1];
    });
    return pairs.slice(0, k).map(p => p[1]);
};
